---@class BehaviorTreeBuilder
local BehaviorTreeBuilder = Class("BehaviorTreeBuilder")

function BehaviorTreeBuilder:__init(context)
    self._context = context
    
    --- 最后创建的节点
    self._currentNode = nil

    --- 堆栈节点
    self._parentNodeStack = {}
end

function BehaviorTreeBuilder:__delete()
   
end

function BehaviorTreeBuilder:SetChildOnParent(child)
   ---@type Behavior
   local parent = BTUtils.Peek(self._parentNodeStack)
    if parent.btType == BehaviorTreeType.Composites then
        parent:AddChild(child)
        
    elseif parent.btType == BehaviorTreeType.Decorator then
        --- 装饰者只有一个子节点，所以自动结束
        parent:SetChild(child)
        
        self:EndDecorator()
        
    end
    
    return self
end

function BehaviorTreeBuilder:EndDecorator()
    self._currentNode = BTUtils.Pop(self._parentNodeStack)
    return self
end

function BehaviorTreeBuilder:PushParentNode(composite)
    if #self._parentNodeStack > 0 then
        self:SetChildOnParent(composite)
    end
    
    BTUtils.Push(self._parentNodeStack, composite)
    
    return self
end

function BehaviorTreeBuilder:EndComposite()
    BTUtils.AssetIsTrue(BTUtils.Peek(self._parentNodeStack).btType == BehaviorTreeType.Composites, "尝试结束复合器，但顶部节点是装饰器")
    
    self._currentNode = BTUtils.Pop(self._parentNodeStack)
    return self
end

---Action
---@param func function
function BehaviorTreeBuilder:Action(func)
    BTUtils.AssetIsFalse(#self._parentNodeStack == 0, "无法创建无嵌套的动作节点, 它必须是一个叶节点")
    return self:SetChildOnParent(ExecuteAction.New(func))
end

function BehaviorTreeBuilder:ActionR(func)
    return self:Action(function(context)
        return func(context) and TaskStatus.Success or TaskStatus.Failure
    end)
end

function BehaviorTreeBuilder:Conditional(func)
    BTUtils.AssetIsFalse(#self._parentNodeStack == 0, "无法创建无嵌套的条件节点, 它必须是一个叶节点")
    return self:SetChildOnParent(ExecuteActionConditional.New(func))
end

function BehaviorTreeBuilder:ConditionalR(func)
    return self:Conditional(function(context)
        return func(context) and TaskStatus.Success or TaskStatus.Failure
    end)
end

function BehaviorTreeBuilder:LogAction(text)
    return self:SetChildOnParent(LogAction.New(text))
end

function BehaviorTreeBuilder:WaitAction(waitTime)
    BTUtils.AssetIsFalse(#self._parentNodeStack == 0, "无法创建无嵌套的动作节点, 它必须是一个叶节点")
    return self:SetChildOnParent(WaitAction.New(waitTime))
end

function BehaviorTreeBuilder:SubTree(subTree)
    BTUtils.AssetIsFalse(#self._parentNodeStack == 0, "无法创建无嵌套的动作节点, 它必须是一个叶节点")
    return self:SetChildOnParent(BehaviorTreeReference.New(subTree))
end

function BehaviorTreeBuilder:ConditionalDecorator(func, shouldReevaluate)
    local conditional = ExecuteActionConditional.New(func)
    return self:PushParentNode(ConditionalDecorator.New(conditional, shouldReevaluate))
    
end

function BehaviorTreeBuilder:ConditionalDecoratorR(func, shouldReevaluate)
    local conditional = ExecuteActionConditional.New(function(context)
        return func(context) and TaskStatus.Success or TaskStatus.Failure
    end)
    return self:PushParentNode(ConditionalDecorator.New(conditional, shouldReevaluate))
end

function BehaviorTreeBuilder:AlwaysSucceed()
    return self:PushParentNode(AlwaysSucceed.New())
end

function BehaviorTreeBuilder:AlwaysFail()
    return self:PushParentNode(AlwaysFail.New())
end

function BehaviorTreeBuilder:Inverter()
    return self:PushParentNode(Inverter.New())
end

