    return self:PushParentNode(UntilFail.New())
end

function BehaviorTreeBuilder:Parallel()
    return self:PushParentNode(Parallel.New())    
end

function BehaviorTreeBuilder:ParallelSelector()
    return self:PushParentNode(ParallelSelector.New())    
end

function BehaviorTreeBuilder:Selector(abortType)
    return self:PushParentNode(Selector.New(abortType))    
end

function BehaviorTreeBuilder:RandomSelector()
    return self:PushParentNode(RandomSelector.New())    
end

function BehaviorTreeBuilder:Sequence(abortType)
    return self:PushParentNode(Sequence.New(abortType))    
end

function BehaviorTreeBuilder:RandomSequence()
    return self:PushParentNode(RandomSequence.New())    
end

function BehaviorTreeBuilder:Build(updatePeriod)
    if self._currentNode == nil then
        printError("无法创建零节点的行为树")
       return  
    end
    return BehaviorTree.New(self._context, self._currentNode, updatePeriod)
end

return BehaviorTreeBuilder
 